    void SetPowerFactor(double? @value);
    /// <summary>
    /// Set switching capacity
    /// </summary>
    void SetSwitchingCapacity(String? @value);
    /// <summary>
    /// Export to JSON string
    /// </summary>
    /// <exception cref="GldfException"></exception>
    String ToJson();
    /// <summary>
    /// Export to pretty JSON string
    /// </summary>
    /// <exception cref="GldfException"></exception>
    String ToPrettyJson();
    /// <summary>
