    public override IntPtr Lower(GldfEngine value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override GldfEngine Lift(IntPtr value) {
        return new GldfEngine(value);
    }

    public override GldfEngine Read(BigEndianStream stream) {
        return Lift(new IntPtr(stream.ReadLong()));
    }

    public override int AllocationSize(GldfEngine value) {
        return 8;
    }

    public override void Write(GldfEngine value, BigEndianStream stream) {
        stream.WriteLong(Lower(value).ToInt64());
    }
}



/// <summary>
/// Parsed EULUMDAT photometric data
/// </summary>
/// <param name="manufacturer">
/// Manufacturer/Header string
/// </param>
/// <param name="luminaire_name">
/// Luminaire name
/// </param>
/// <param name="luminaire_number">
/// Luminaire number
/// </param>
/// <param name="lamp_type">
/// Lamp type description
/// </param>
/// <param name="total_lumens">
/// Total luminous flux in lumens
/// </param>
/// <param name="lorl">
/// Light Output Ratio Luminaire (%)
/// </param>
/// <param name="c_plane_count">
/// Number of C planes
/// </param>
/// <param name="gamma_count">
/// Number of gamma angles
/// </param>
/// <param name="symmetry">
/// Symmetry indicator (0-4)
/// </param>
/// <param name="c_angles">
/// C plane angles in degrees
/// </param>
/// <param name="gamma_angles">
/// Gamma angles in degrees
/// </param>
/// <param name="intensities">
/// Intensity values organized by C plane, then by gamma
/// Access as: intensities[c_plane_index * gamma_count + gamma_index]
/// </param>
/// <param name="max_intensity">
/// Maximum intensity value (for normalization)
/// </param>
/// <param name="conversion_factor">
/// Unit conversion factor
/// </param>
/// <param name="luminaire_dimensions">
/// Luminaire dimensions in mm [length, width, height]
/// </param>
/// <param name="luminous_area_dimensions">
/// Luminous area dimensions in mm [length, width]
/// </param>
/// <param name="dff">
/// Downward flux fraction (%)
/// </param>
/// <param name="color_temperature">
/// Color temperature (K)
/// </param>
/// <param name="wattage">
/// Wattage (W)
/// </param>
public record EulumdatData (
    /// <summary>
    /// Manufacturer/Header string
    /// </summary>
    String @manufacturer, 
    /// <summary>
    /// Luminaire name
    /// </summary>
    String @luminaireName, 
    /// <summary>
    /// Luminaire number
    /// </summary>
    String @luminaireNumber, 
    /// <summary>
    /// Lamp type description
    /// </summary>
    String @lampType, 
    /// <summary>
    /// Total luminous flux in lumens
    /// </summary>
    double @totalLumens, 
    /// <summary>
    /// Light Output Ratio Luminaire (%)
    /// </summary>
    double @lorl, 
    /// <summary>
    /// Number of C planes
    /// </summary>
    int @cPlaneCount, 
    /// <summary>
    /// Number of gamma angles
    /// </summary>
    int @gammaCount, 
    /// <summary>
    /// Symmetry indicator (0-4)
    /// </summary>
    int @symmetry, 
    /// <summary>
    /// C plane angles in degrees
    /// </summary>
    List<double> @cAngles, 
    /// <summary>
    /// Gamma angles in degrees
    /// </summary>
    List<double> @gammaAngles, 
    /// <summary>
    /// Intensity values organized by C plane, then by gamma
    /// Access as: intensities[c_plane_index * gamma_count + gamma_index]
    /// </summary>
    List<double> @intensities, 
    /// <summary>
    /// Maximum intensity value (for normalization)
    /// </summary>
    double @maxIntensity, 
    /// <summary>
    /// Unit conversion factor
    /// </summary>
    double @conversionFactor, 
    /// <summary>
    /// Luminaire dimensions in mm [length, width, height]
    /// </summary>
    List<double> @luminaireDimensions, 
    /// <summary>
    /// Luminous area dimensions in mm [length, width]
    /// </summary>
    List<double> @luminousAreaDimensions, 
    /// <summary>
    /// Downward flux fraction (%)
    /// </summary>
    double @dff, 
    /// <summary>
    /// Color temperature (K)
    /// </summary>
    String @colorTemperature, 
    /// <summary>
    /// Wattage (W)
    /// </summary>
    double @wattage
) {
}

