public class GldfException: UniffiException {
    GldfException() : base() {}
    GldfException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class ParseException : GldfException {
        // Members
        public String @msg;

        // Constructor
        public ParseException(
                String @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    
    
    public class SerializeException : GldfException {
        // Members
        public String @msg;

        // Constructor
        public SerializeException(
                String @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    
    
    public class FileNotFound : GldfException {
        // Members
        public String @msg;

        // Constructor
        public FileNotFound(
                String @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    
    
    public class InvalidData : GldfException {
        // Members
        public String @msg;

        // Constructor
        public InvalidData(
                String @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    

    
}

class FfiConverterTypeGldfError : FfiConverterRustBuffer<GldfException>, CallStatusErrorHandler<GldfException> {
    public static FfiConverterTypeGldfError INSTANCE = new FfiConverterTypeGldfError();

    public override GldfException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new GldfException.ParseException(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new GldfException.SerializeException(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new GldfException.FileNotFound(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new GldfException.InvalidData(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeGldfError.Read()", value));
        }
    }

    public override int AllocationSize(GldfException value) {
        switch (value) {

            case GldfException.ParseException variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);

            case GldfException.SerializeException variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);

            case GldfException.FileNotFound variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);

            case GldfException.InvalidData variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeGldfError.AllocationSize()", value));
        }
    }

    public override void Write(GldfException value, BigEndianStream stream) {
        switch (value) {
            case GldfException.ParseException variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            case GldfException.SerializeException variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            case GldfException.FileNotFound variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            case GldfException.InvalidData variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeGldfError.Write()", value));
        }
    }
}




